-- GENERATED by `wfj generate` from data/gossip/gossip-17.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["17082d74bdcd148a"] = { "I liquidi e le miscele ribollono e sussultano al tuo avvicinarti. Accanto all'attrezzatura c'è un grosso paio di pinze che sembrano adatte per immergere campioni di melma.\n\nC'è dell'equipaggiamento di sicurezza, ma sembra impolverato e del tutto trascurato.\n\nMetti alcuni dei tuoi campioni nei becher?", "." },
  ["17083ecc103a83c8"] = { "Qui si combatté una grande battaglia. Molte grandi battaglie.", "." },
  ["170d82f55f970d57"] = { "Toglietemi di dosso {name}!", "." },
  ["170e1afd7c60826a"] = { "È un tentativo di salvataggio! Che nessuno fugga!", "." },
  ["1716814716d405aa"] = { "Ho perso la ⟦Cache of Mau'ari=Cassa di Mau'ari⟧. Cosa posso fare?", "." },
  ["171c2adf44343f45"] = { "Quarantadue... quarantadue... quarantadue cosa? Potrebbe essere qualsiasi cosa! Quarantadue... mmh...", "." },
  ["171c7ccf93aaa75a"] = { "A pensarci bene, quasi tutti quelli coinvolti sono morti. Capirò se non vorrai avere niente a che fare con tutto questo, {name}.", "." },
  ["173a16ff666775c1"] = { "Pretese che tornassimo immediatamente all'⟦Hive'Regal=Alveare Regal⟧! Brann non volle sentire storie. Le disse che non saremmo mai tornati in quegli alveari senza un esercito alle spalle. Era diventato troppo pericoloso. Il numero di quei puzzolenti insetti sembrava triplicato dalla prima volta che c'eravamo addentrati.\n\nFu allora che Natalia perse la testa!", "." },
  ["173fa354867e0b97"] = { "Sì, ma lo troverai più gratificante se hai abilità nell'erbalismo! Dovrai curare e coltivare semi speciali, non menare un'ascia alla cieca o gesticolare come un forsennato contro le ombre che passano. Anche se lo ⟦Evergreen Pouch=Zaino Sempreverde⟧ che riceverai permette perfino al bruto più sempliciotto di far crescere qualcosa, chi mostra un po' di talento otterrà raccolti più abbondanti.", "." },
  ["174d2b1041690292"] = { "Tenetevi pronti!", "." },
  ["174e19e0c0b7f516"] = { "Incredibile! Credo di averlo trovato, {name}!", "." },
  ["17502dbe82ea678c"] = { "È possibile per chi non è della stirpe dei draghi ottenere l'Adorned Seal of Ascension e attraversare la barriera protettiva. Mentre il possesso di un simile oggetto mi distruggerebbe di certo, forse tu potresti usarlo per abbassare la barriera.", "." },
  ["17571d7f5352ca95"] = { "Possiamo renderlo migliore, più forte, più veloce. Abbiamo la tecnologia. Abbiamo la magia.", "." },
  ["1757c66b040af734"] = { "Non c'è molto da raccontare. Vivevo nel villaggio di Falaath e quando arrivò il culto capii da che parte tirava il vento. Mi rasai la testa, indossai le vesti grigie e dissi le parole che volevano sentire. \r\n\nOra cerco solo di sopravvivere. Perlopiù tengo la testa bassa e faccio il mio mestiere per quella svitata di Lorthuna.", "." },
  ["1757fab5ea2249cb"] = { "Per le Fauci di Drago!", "." },
  ["17597c4f6d3b6e77"] = { "Il ⟦Stonehearth Graveyard=Cimitero di Cordipietra⟧ si trova a est dell'⟦Stonehearth Outpost=Avamposto di Cordipietra⟧, nel ⟦Field of Strife=Pian della Discordia⟧.\n\nAl momento è sotto il controllo dell'⟦Horde=Orda⟧.", "." },
  ["176573d15f8ae461"] = { "Cosa pensi di Dadanga?", "." },
  ["1768596c4d2b31e1"] = { "Ah! Non puoi neanche immaginare quanto siano inutili i tuoi sforzi.", "." },
  ["176d454f21d43ff9"] = { "⟦Darrowshire=Borgo di Darrow⟧ cadrà!", "." },
  ["176fbb22e1621ae4"] = { "%s ride istericamente.", "." },
  ["1771cb4e96a50b76"] = { "Eccellente! Soddisfi i parametri e le specifiche richiesti. Cosa posso fare per te?", "." },
  ["17724e41958126b0"] = { "Mi farebbe piacere insegnarti! Così mia sorella vedrà che non è l'unica a saperne qualcosa di ingegneria...", "." },
  ["1772f49f70900e3c"] = { "Solo uno stolto resterebbe in questa battaglia. Addio, <codardo/codarda>.", "." },
  ["177de68bda8d97f3"] = { "Certo che parlo da solo. È l'unico modo per fare una conversazione decente in questa città.", "." },
  ["177e44d6e5ff41b5"] = { "Di cosa ha bisogno adesso fratello Paxton?", "." },
  ["178c492ebd8d6d2d"] = { "Sul'thraze... la prima volta che ho sentito pronunciare questa parola avevo più o meno la tua età. Allora non significava nulla per me, così come non significa nulla per te adesso. Solo quando una banda di guerra di troll venuti da ⟦Zul'Farrak=Zul'farrak⟧ devastò queste terre capii... e ne ebbi paura.\n\nIn molti ti diranno che la Splitblade of Suffering non esiste. Che è un mito, una diceria messa in giro per far rigare dritto i bambini. Ma credimi, {race}, esiste.\n\n<Trenton si distrae mentre si passa la mano sulla cicatrice frastagliata che ha sul volto.>", "." },
  ["1793313e43d31bc3"] = { "Lunga vita al re, baby!", "." },
  ["179359d48b23d360"] = { "A quanto pare vi serve un'altra lezione, mortali!", "." },
  ["179577266b14232a"] = { "Quanto manca ancora?", "." },
  ["1796eb07e4f9d918"] = { "Ti prego, lascia in pace un vecchio spirito.", "." },
  ["179870bd3886c854"] = { "Addio a te, e che Elune sia sempre con te.", "." },
  ["17a5cd607d280ac9"] = { "Che c'è da chiedere? È una scimmia, <pazzo/pazza> che non sei altro. Comunque, sì, la scimmia andò su tutte le furie dopo aver visto il vecchio Brann finire a faccia in giù nella sabbia. Qualunque cosa facesse l'elfa della notte, non c'era verso di impedire al qui presente Glibb di martellarle la zucca.", "." },
  ["17a776514759adb5"] = { "Il capo vuole tutti in stato di massima allerta. L'ancora arrugginita affonda stanotte.", "." },
  ["17a87505bc24fe6a"] = { "Non ricevo molte visite. Stai cercando qualcosa in particolare, vero?", "." },
  ["17b1337b66748ed1"] = { "Me ne vado da qui!", "." },
  ["17b258608a2ccc2c"] = { "%s avvolge la torre di sentinella. La torre è in fiamme!", "." },
  ["17b99cfa1b3c8d32"] = { "Osate disturbare il nostro lavoro?! Il padrone non ne sarà contento. Approfittate di questo tempo per prepararvi... quando torneremo, ci lasceremo dietro solo morte e distruzione!", "." },
  ["17c1169563275e53"] = { "Non ho altra scelta che obbedire!", "." },
  ["17c433a72b772170"] = { "Sta' attent<o/a> a dove metti i piedi da queste parti, <figliolo/ragazza>. Non farai parte della nostra squadra, ma questo non vuol dire che non ti prenda a bastonate se non righi dritto!", "." },
  ["17c5f86be03dc89f"] = { "Grazie per i rottami d'armatura, {name}!", "." },
  ["17cac50126a1ba91"] = { "Che ci fai a girare qua intorno? Perché quei pesci piccoli non stanno in catene?!", "." },
  ["17ce36eb45f28124"] = { "Cacciarmi, eh!? Mostrerò a quei bacchettoni con il cappello a punta di ⟦Stormwind=Roccavento⟧ il vero potere di Niby! AMMIRATE!", "." },
  ["17d17fec64329f1b"] = { "Sono passati così tanti anni dal mio noviziato che non credo di essere la persona più adatta a insegnarti. Prova a parlare con Tarn o Mak, proprio lì. Uno dei due dovrebbe saper rispondere alle tue domande.", "." },
  ["17d1eb4cd51d060d"] = { "Skwol! Possiedo il tuo scettro! Ti ordino di entrare in questo mondo!", "." },
  ["17d7d70c240756e6"] = { "Cos'è questa storia? Vuoi rovinarmi la reputazione? Io non insegno ai novellini, <amico/bella>. Prova a parlare con l'orco Whuut, nel Drag di Orgrimmar. È molto più vicino al tuo livello di abilità. E di cervello.", "." },
  ["17dec6d041e6f2d6"] = { "Un Ash'ari Crystal è stato abbattuto! Ripristinate lo ziggurat prima che la Necropoli diventi vulnerabile!", "." },
  ["17edb854d59e6e4a"] = { "Guarda questo campo devastato e comprendi il potere che gli elementi custodiscono, {race}.", "." },
  ["17f1fe9f73a623df"] = { "Ora cerchiamo l'erba.", "." },
  ["17fbaa9cce97c9e3"] = { "Plucky? Ho sentito che il maestro di corsa Kronkrider, su in cima alla torre, sa dove si trova.", "." },
  ["17fe947a12981858"] = { "La Madre Terra chiama e tu rispondi. Troverai la Hall of Spirits sull'⟦Spirit Rise=Altura degli Spiriti⟧.", "." },
})
